// </precache>

const CACHE = `agescope-${VERSION}`; // earlier working name, kept so old caches are found and removed

async function hash12(buf) {
  const d = new Uint8Array(await crypto.subtle.digest('SHA-256', buf));
  return Array.from(d.slice(0, 6), (b) => b.toString(16).padStart(2, '0')).join('');
}

const stored = (buf, res) => new Response(buf, {
  status: 200,
  headers: { 'Content-Type': res.headers.get('Content-Type') || 'application/octet-stream' },
});

// Install: reuse every file of an older version whose content is unchanged (checked by
// hash), download only the rest. ?v=<hash> makes the CDN return the new file, and the
// hash check makes the update all-or-nothing (a half-deployed site is retried later).
async function precache(cache, oldKeys, [path, hash]) {
  for (const key of oldKeys) {
    const hit = await (await caches.open(key)).match(path);
    if (!hit) continue;
    const buf = await hit.arrayBuffer();
    if ((await hash12(buf)) === hash) return cache.put(path, stored(buf, hit));
  }
  const res = await fetch(new Request(`${path}?v=${hash}`, { cache: 'reload' }));
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  const buf = await res.arrayBuffer();
  if ((await hash12(buf)) !== hash) throw new Error(`${path}: the server does not have this version yet`);
  return cache.put(path, stored(buf, res));
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const oldKeys = (await caches.keys()).filter((k) => k.startsWith('agescope-') && k !== CACHE);
    const queue = [...PRECACHE];
    const worker = async () => {
      while (queue.length) await precache(cache, oldKeys, queue.shift());
    };
    await Promise.all([worker(), worker(), worker(), worker()]);
    // Wait for the user's consent ("Install and restart", message below) only if
    // an open page of EdgeLens supports that step. Pages of older versions do not
    // answer the handshake; they expect the new version to switch itself on.
    if (!(await pagesAskForConsent())) await self.skipWaiting();
  })());
});

async function pagesAskForConsent() {
  const pages = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  const answers = await Promise.all(pages.map((page) => new Promise((resolve) => {
    const ch = new MessageChannel();
    ch.port1.onmessage = (e) => resolve(e.data?.consent === true);
    page.postMessage({ type: 'update-handshake' }, [ch.port2]);
    setTimeout(() => resolve(false), 1500);
  })));
  return answers.some(Boolean);
}

self.addEventListener('message', (event) => {
  if (event.data?.type === 'version') event.ports[0]?.postMessage({ version: VERSION });
  if (event.data?.type === 'skipWaiting') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('agescope-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

function isolate(response) {
  if (!response || response.status === 0 || response.type === 'opaque') return response;
  const headers = new Headers(response.headers);
  headers.set('Cross-Origin-Embedder-Policy', 'require-corp');
  headers.set('Cross-Origin-Opener-Policy', 'same-origin');
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // Model cards are small and change when models are re-exported: network first.
    if (req.url.includes('/models/') && req.url.endsWith('.json')) {
      try {
        return isolate(await fetch(req));
      } catch {
        return isolate(await cache.match(req, { ignoreSearch: true }));
      }
    }
    let res = await cache.match(req, { ignoreSearch: true });
    if (!res) {
      try {
        res = await fetch(req);
      } catch (err) {
        if (req.mode === 'navigate') res = await cache.match('index.html');
        if (!res) throw err;
      }
    }
    return isolate(res);
  })());
});
